Let's implement CPF:

static void CPF(char pattern[PATTERN_SIZE], int32_t kmpNext[PATTERN_SIZE]) {
    int32_t cnd = 0;
    kmpNext[0] = 0;
    int32_t pos = 1;
    while (pos != PATTERN_SIZE) {
        if (pattern[pos] == pattern[cnd]) {
            cnd++;
            kmpNext[pos] = cnd;
            pos++;
        } else if (cnd != 0) {
            cnd = kmpNext[cnd - 1];
        } else {
            kmpNext[pos] = 0;
            pos++;
        }
    }
}
This is standard.

